import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Facts & State","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/facts.md","filePath":"concepts/facts.md"}'),d={name:"concepts/facts.md"};function o(i,e,c,r,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="facts-state" tabindex="-1">Facts &amp; State <a class="header-anchor" href="#facts-state" aria-label="Permalink to &quot;Facts &amp; State&quot;">​</a></h1><p>Everything in CCattler is a fact — a key-value pair stored in etcd. Facts are not mutable objects with methods. They are observations: &quot;service web should have 3 instances&quot;, &quot;instance a8f31 is running on node-2&quot;, &quot;node-1 has 4 CPUs available&quot;.</p><h2 id="three-state-namespaces" tabindex="-1">Three state namespaces <a class="header-anchor" href="#three-state-namespaces" aria-label="Permalink to &quot;Three state namespaces&quot;">​</a></h2><p>The most important structural choice in CCattler is the separation of desired and observed state:</p><table tabindex="0"><thead><tr><th>Namespace</th><th>Who writes</th><th>What it contains</th></tr></thead><tbody><tr><td><code>desired/</code></td><td>Users, policy controllers, autoscaler</td><td>What the world should look like</td></tr><tr><td><code>observed/</code></td><td>Node agents</td><td>What the world actually looks like</td></tr><tr><td><code>effective/</code></td><td>Intent resolver</td><td>Computed desired state after policy</td></tr><tr><td><code>placement/</code></td><td>Scheduler</td><td>Where instances should run</td></tr><tr><td><code>endpoint/</code></td><td>Network controller</td><td>Derived network state</td></tr></tbody></table><p>A compromised node agent can write to <code>observed/</code> but never to <code>desired/</code>. This boundary is the foundation of the security model.</p><h2 id="core-fact-types" tabindex="-1">Core fact types <a class="header-anchor" href="#core-fact-types" aria-label="Permalink to &quot;Core fact types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fact</th><th>Fields</th><th>Description</th></tr></thead><tbody><tr><td><code>service</code></td><td>name, image, instances, port</td><td>A workload definition</td></tr><tr><td><code>instance</code></td><td>id, service, node, state</td><td>One running unit of a service</td></tr><tr><td><code>node</code></td><td>id, cpu, memory, state</td><td>A machine in the cluster</td></tr><tr><td><code>endpoint</code></td><td>service, instance, address, port</td><td>Network reachability</td></tr><tr><td><code>volume</code></td><td>name, size, persistent</td><td>Storage</td></tr><tr><td><code>placement</code></td><td>instance, node</td><td>Scheduling decision</td></tr><tr><td><code>config</code></td><td>service, key, value, type</td><td>Environment variable or file</td></tr><tr><td><code>secret</code></td><td>name</td><td>Secret exists (value in encrypted store)</td></tr><tr><td><code>secret_grant</code></td><td>service, secret_name</td><td>Service authorized to access secret</td></tr><tr><td><code>probe</code></td><td>service, type, method, interval</td><td>Health check configuration</td></tr><tr><td><code>probe_state</code></td><td>instance, type, state</td><td>Observed health result</td></tr><tr><td><code>node_label</code></td><td>node, label, value</td><td>Key-value label for placement</td></tr></tbody></table><h2 id="intent-layers" tabindex="-1">Intent layers <a class="header-anchor" href="#intent-layers" aria-label="Permalink to &quot;Intent layers&quot;">​</a></h2><p>Multiple writers can contribute facts without fighting over the same object. Each writes to its own intent prefix:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>intent/user/service/web/instances        → 3      (user declared min=3)</span></span>
<span class="line"><span>intent/autoscaler/service/web/instances  → 5      (autoscaler recommends 5)</span></span></code></pre></div><p>The intent resolver computes the effective value:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>effective/service/web/instances → 5</span></span></code></pre></div><p>The instance controller watches <code>effective/</code>, not <code>desired/</code> or <code>intent/</code>. It doesn&#39;t know or care <em>why</em> the desired count is 5.</p><h2 id="flat-facts-not-nested-objects" tabindex="-1">Flat facts, not nested objects <a class="header-anchor" href="#flat-facts-not-nested-objects" aria-label="Permalink to &quot;Flat facts, not nested objects&quot;">​</a></h2><p>Each fact is its own key. This enables:</p><ul><li><strong>Fine-grained watches</strong> — <code>Watch(&quot;observed/instance/&quot;)</code> for all instance changes</li><li><strong>Atomic field updates</strong> — change one field without read-modify-write on a blob</li><li><strong>Prefix scans</strong> — query <code>desired/service/web/</code> to get all facts about the web service</li></ul><p>Example keys for a running instance:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>observed/instance/a8f31/service    → &quot;web&quot;</span></span>
<span class="line"><span>observed/instance/a8f31/node       → &quot;node-2&quot;</span></span>
<span class="line"><span>observed/instance/a8f31/state      → &quot;running&quot;</span></span>
<span class="line"><span>observed/instance/a8f31/image      → &quot;nginx:1.28&quot;</span></span>
<span class="line"><span>observed/instance/a8f31/ip         → &quot;10.1.0.5&quot;</span></span>
<span class="line"><span>observed/instance/a8f31/health     → &quot;healthy&quot;</span></span></code></pre></div><h2 id="revisions-and-optimistic-concurrency" tabindex="-1">Revisions and optimistic concurrency <a class="header-anchor" href="#revisions-and-optimistic-concurrency" aria-label="Permalink to &quot;Revisions and optimistic concurrency&quot;">​</a></h2><p>etcd provides a global revision number. Every mutation increments it. Transactions use revision-based compare-and-swap:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transaction:</span></span>
<span class="line"><span>    IF   desired/service/web  mod_revision == 8172</span></span>
<span class="line"><span>    THEN PUT desired/service/web/instances = 5</span></span>
<span class="line"><span>    ELSE FAIL (re-read and retry)</span></span></code></pre></div><p>This prevents conflicts — two schedulers can&#39;t double-place an instance:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transaction:</span></span>
<span class="line"><span>    IF   placement/instance/a8f31  create_revision == 0  (does not exist)</span></span>
<span class="line"><span>    THEN PUT placement/instance/a8f31 = &quot;node-2&quot;</span></span>
<span class="line"><span>    ELSE FAIL (already placed)</span></span></code></pre></div><h2 id="leases-for-node-liveness" tabindex="-1">Leases for node liveness <a class="header-anchor" href="#leases-for-node-liveness" aria-label="Permalink to &quot;Leases for node liveness&quot;">​</a></h2><p>Each node agent creates an etcd lease (TTL 30s) and continuously refreshes it. If the agent crashes:</p><ol><li>Lease expires</li><li>Failure controller detects it</li><li>Node marked as <code>unreachable</code></li><li>Instances on that node get rescheduled</li></ol><p>No explicit health checks between control plane and nodes — the lease mechanism handles liveness.</p>`,28)])])}const b=t(d,[["render",o]]);export{u as __pageData,b as default};
